"""content/seed.json → supabase/seed.sql (sample course dates, passages and fleet)."""
import json, os
WEB = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
s = json.load(open(f'{WEB}/content/seed.json'))
q = lambda v: 'null' if v is None else str(v) if isinstance(v, (int, float)) else "'" + str(v).replace("'", "''") + "'"
out = ['-- Sample data for Ocean Way (generated by scripts/make_seed_sql.py)', 'begin;']
out.append('insert into public.course_dates (key, course_slug, starts_on, ends_on, area, boat, meeting_point, price_eur, places_total, places_held) values')
out.append(',\n'.join(f"  ({q(d['key'])}, {q(d['course_slug'])}, {q(d['starts_on'])}, {q(d['ends_on'])}, {q(d['area'])}, {q(d['boat'])}, {q(d['meeting_point'])}, {d['price_eur']}, {d['places_total']}, {d['places_taken']})" for d in s['course_dates']) + '\non conflict (course_slug, key) do nothing;')
out.append('insert into public.passages (key, starts_on, ends_on, from_port, to_port, leg, waters, price_eur, places_total) values')
out.append(',\n'.join(f"  ({q(p['key'])}, {q(p['starts_on'])}, {q(p['ends_on'])}, {q(p['from_port'])}, {q(p['to_port'])}, {q(p['leg'])}, {q(p['waters'])}, {p['price_eur']}, {p['places_total']})" for p in s['passages']) + '\non conflict (key) do nothing;')
for p in s['passages']:
    if p['return_key']:
        out.append(f"update public.passages set return_id = (select id from public.passages where key = {q(p['return_key'])}) where key = {q(p['key'])};")
if s['yachts']:  # the fleet itself is in supabase/seed_fleet.sql
    out.append('insert into public.yachts (sort, model, year, length_m, cabins, berths, base, used_for, charter_from_eur, photo_id, photo_alt) values')
    out.append(',\n'.join(f"  ({y['sort']}, {q(y['model'])}, {y['year']}, {y['length_m']}, {y['cabins']}, {y['berths']}, {q(y['base'])}, {q(y['used_for'])}, {y['charter_from_eur']}, {q(y['photo_id'])}, {q(y['photo_alt'])})" for y in s['yachts']) + ';')
out.append('commit;')
open(f'{WEB}/supabase/seed.sql', 'w').write('\n'.join(out) + '\n')
print('seed.sql written')
